draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // background elements
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(50, H/2);
  ctx.lineTo(W-50, H/2);
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-75, 100, 150);
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // characters
  ctx.beginPath();
  ctx.arc(W/2-100, H/2-100, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2+80, H/2-100, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // apply wisdom
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2-100, H/2+50 + 50*Math.sin(t));

  // lesson life
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson', W/2+80, H/2+50 + 50*Math.cos(t));

  ctx.restore();
}
